SELECT percentile_cont(0.75) within GROUP (ORDER BY procedure_duration) AS q75, percentile_cont(0.90) within GROUP (ORDER BY procedure_duration) AS q90 FROM procedures_in_first_24_hours WHERE subject_id IN (SELECT subject_id FROM icu_patients); SELECT (SELECT AVG(los) FROM age_matched_icu_patients) AS avg_icu_los, (SELECT AVG(drg_mortality) FROM age_matched_icu_patients) AS avg_hospital_mortality;